functions.scheduleBastardLoopXSingleVoice:
function scheduleBastardLoopXSingleVoice(step, scheduledTime, stepDuration, nextStep, options = {}) {
    if (isBastardLoopXUsingSynth()) return playBastardLoopXSynthVoice(step, scheduledTime, stepDuration, nextStep, options);
    if (!audioContext || !bastardLoopXSampleBuffer || !step?.note) return;
    const source = audioContext.createBufferSource();
    const gain = audioContext.createGain();
    const filters = createBastardLoopConfigurableFilters(getBastardLoopXFilterCutoff(), getBastardLoopXFilterMode());
    const level = getBastardLoopXLevelValue();
    if (level <= 0) return;
    const destination = ensureBastardLoopXDelayBus(getBastardLoopXPlaybackDestination());
    if (!destination) return;
    const levelScale = Math.max(0.32, Math.min(1, Number(options.levelScale) || 1));
    const pitchRatio = Math.max(0.125, Math.min(8, getBastardLoopXPitchRatioForNote(step.note)));
    const lengthRatio = getBastardLoopXStepLengthRatio();
    const decayRatio = getBastardLoopXDecayRatio();
    const startTrimRatio = getBastardLoopXStartTrimRatio();
    const attackTime = Math.max(0.001, getBastardLoopXAttackSeconds());
    const sourceRegion = getBastardLoopXSampleRegion();
    const startOffsetSeconds = Math.max(sourceRegion.start, Math.min(Math.max(sourceRegion.start, sourceRegion.end - 0.01), sourceRegion.start + (sourceRegion.end - sourceRegion.start) * startTrimRatio));
    const remainingDuration = Math.max(0.02, (sourceRegion.end - startOffsetSeconds) / pitchRatio);
    const sustainDuration = Math.max(0.02, remainingDuration * lengthRatio);
    const voiceWindow = Math.max(0.02, Number(options.stepWindow) || stepDuration);
    const slideDuration = step.slide && nextStep?.note ? voiceWindow * 2 : voiceWindow;
    const allowFullTail = decayRatio >= 0.999;
    const duration = allowFullTail
        ? Math.max(remainingDuration, slideDuration * 0.98)
        : Math.max(sustainDuration, slideDuration * 0.98);
    const decayEndTime = scheduledTime + Math.max(attackTime + 0.02, duration * Math.max(0.08, decayRatio));
    const endTime = scheduledTime + duration;

    source.buffer = bastardLoopXSampleBuffer;
    source.playbackRate.setValueAtTime(pitchRatio, scheduledTime);
    if (step.slide && nextStep?.note) {
        const nextRatio = Math.max(0.125, Math.min(8, getBastardLoopXPitchRatioForNote(nextStep.note)));
        source.playbackRate.linearRampToValueAtTime(nextRatio, scheduledTime + stepDuration);
    }

    gain.gain.setValueAtTime(0.0001, scheduledTime);
    gain.gain.linearRampToValueAtTime(Math.max(0.0001, level * levelScale), scheduledTime + attackTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, Math.min(endTime, decayEndTime));

    source.connect(gain);
    connectBastardLoopFilterChain(gain, filters, destination, 'X', source);
    applyBastardLoopXFilterEnvelope(filters, scheduledTime, duration, step);

    const voice = { source, gain, filterNodes: filters };
    attachBastardLoopXFilterLfoToVoice(voice, getBastardLoopXFilterCutoff());
    bastardLoopXActiveVoices.add(voice);
    source.onended = () => {
        bastardLoopXActiveVoices.delete(voice);
        destroyBastardLoopXVoiceLfo(voice);
        try {
            source.disconnect();
            gain.disconnect();
            disconnectBastardLoopFilterChain(filters);
        } catch (error) {}
    };
    source.patternSectionStart = scheduledTime;
    source.start(scheduledTime, startOffsetSeconds, sourceRegion.end - startOffsetSeconds);
    scheduleTransportSourceStop(source, endTime + 0.02);
}

functions.previewBastardLoopXStep:
function previewBastardLoopXStep(step, options = {}) {
    if (isBastardLoopXUsingSynth()) return auditionBastardLoopXVoice(step);
    if (!audioContext || !bastardLoopXSampleBuffer || !step?.note || step.rest) return false;
    const source = audioContext.createBufferSource();
    const gain = audioContext.createGain();
    const filters = createBastardLoopConfigurableFilters(getBastardLoopXFilterCutoff(), getBastardLoopXFilterMode());
    const level = getBastardLoopXAuditionLevel();
    const destination = ensureBastardLoopXDelayBus(getBastardLoopXPlaybackDestination());
    if (!destination) return false;
    const pitchRatio = Math.max(0.125, Math.min(8, getBastardLoopXPitchRatioForNote(step.note)));
    const now = (audioContext.currentTime || 0) + 0.002;
    const startTrimRatio = getBastardLoopXStartTrimRatio();
    let attackTime = Math.max(0.001, getBastardLoopXAttackSeconds());
    const sourceRegion = getBastardLoopXSampleRegion();
    const startOffsetSeconds = Math.max(sourceRegion.start, Math.min(Math.max(sourceRegion.start, sourceRegion.end - 0.01), sourceRegion.start + (sourceRegion.end - sourceRegion.start) * startTrimRatio));
    const remainingDuration = Math.max(0.08, (sourceRegion.end - startOffsetSeconds) / pitchRatio);
    const decayRatio = getBastardLoopXDecayRatio();
    const allowFullTail = decayRatio >= 0.999;
    const previewDuration = options.keyHold ? remainingDuration : allowFullTail
        ? Math.max(0.08, Math.min(remainingDuration, 4))
        : Math.max(0.08, Math.min(1.4, remainingDuration * Math.max(0.18, getBastardLoopXStepLengthRatio())));
    const fadeEndTime = now + Math.max(0.05, previewDuration * Math.max(0.16, getBastardLoopXDecayRatio()));
    const stopTime = now + previewDuration;
    attackTime = Math.min(attackTime, previewDuration * 0.4);
    source.buffer = bastardLoopXSampleBuffer;
    source.playbackRate.setValueAtTime(pitchRatio, now);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.linearRampToValueAtTime(Math.max(0.0001, level), now + attackTime);
    if (options.keyHold) {
        gain.gain.setValueAtTime(Math.max(0.0001, level), Math.max(now + attackTime, stopTime - 0.008));
        gain.gain.linearRampToValueAtTime(0.0001, stopTime);
    } else {
        gain.gain.exponentialRampToValueAtTime(0.0001, Math.min(stopTime, fadeEndTime));
    }
    source.connect(gain);
    connectBastardLoopFilterChain(gain, filters, destination, 'X', source);
    applyBastardLoopXFilterEnvelope(filters, now, previewDuration, step);
    const voice = { source, gain, filterNodes: filters };
    attachBastardLoopXFilterLfoToVoice(voice, getBastardLoopXFilterCutoff());
    if (options.keyHold) options.keyHold.voice = voice;
    else bastardLoopXActiveVoices.add(voice);
    source.onended = () => {
        if (options.keyHold) options.keyHold.voice = null;
        bastardLoopXActiveVoices.delete(voice);
        destroyBastardLoopXVoiceLfo(voice);
        try {
            source.disconnect();
            gain.disconnect();
            disconnectBastardLoopFilterChain(filters);
        } catch (error) {}
    };
    source.start(now, startOffsetSeconds, sourceRegion.end - startOffsetSeconds);
    source.stop(stopTime + 0.02);
    return true;
}
